import{j as e}from"./blog-pages-Be79NB64.js";import{P as n}from"./compare-pages-Bd0G6RZ9.js";const r=[{factor:"Connection method",atlantis:"REST via Oracle Integration Cloud (OIC)",competitor:"Oracle Fusion ERP Cloud REST APIs"},{factor:"Supported Oracle versions",atlantis:"Oracle Fusion ERP Cloud (current), Oracle EAM Cloud, Oracle E-Business Suite (legacy via OIC)",competitor:"—"},{factor:"Authentication",atlantis:"OAuth2 client credentials via Oracle Identity Cloud Service",competitor:"—"},{factor:"Asset master sync",atlantis:"Bi-directional, Oracle master of record",competitor:"—"},{factor:"Work order flow",atlantis:"Atlantis raises Service Request, Oracle creates Work Order, status flows back",competitor:"—"},{factor:"Cost actuals → Atlantis",atlantis:"On Work Order completion, actual cost + completion date sync back",competitor:"—"},{factor:"Deployment time",atlantis:"3–5 weeks typical",competitor:"—"},{factor:"Oracle prerequisites",atlantis:"Oracle Integration Cloud subscription, OAuth2 setup, dedicated integration user",competitor:"—"},{factor:"Rate limits",atlantis:"Standard OIC throttling — managed by integration scheduler",competitor:"—"}],i=[{question:"Does this work with Oracle E-Business Suite as well as Fusion?",answer:"Yes, via Oracle Integration Cloud (OIC). Oracle Fusion ERP Cloud has a clean REST API surface — direct integration is straightforward. Oracle E-Business Suite (EBS) is older and the integration goes through OIC&rsquo;s EBS adapter, which abstracts the older PL/SQL and database interfaces. The functional integration is the same from Atlantis&rsquo; perspective; only the transport differs."},{question:"Which Oracle modules do you sync?",answer:"Asset, Work Order, Service Request, Maintenance Plan, Job Plan, Cost Center, Customer / Supplier where relevant. Inspection findings flow Atlantis → Oracle as Service Requests which then route into the standard Oracle Maintenance Work Order workflow. Cost actuals and Work Order completion flow back. Adjacent modules (Oracle Project, Oracle Procurement, Oracle Financials) can be integrated in subsequent phases if the use case requires."},{question:"What about Oracle EAM specifically?",answer:"Oracle EAM Cloud is supported as a first-class target. The integration patterns are the same as for Oracle Fusion ERP Cloud but the data model maps to EAM-specific objects (Asset Number, Asset Group, Maintenance Activity, Resource). Customers running both Oracle Financials and Oracle EAM Cloud get a single integration point with both modules."},{question:"How does FFS/RBI flow into Oracle?",answer:"API 579 FFS results and API 581 RBI risk-band changes flow into Oracle as Service Requests with structured long-text containing the calculation summary, the recommended action, and a deep link back to the full Atlantis record. Risk-band escalations (Medium → High) trigger automatic Service Request creation; the Service Request priority is set based on risk band per your site&rsquo;s mapping rules. Risk-driven inspection interval changes flow into the Oracle Maintenance Plan to update the next due date."},{question:"What about Oracle Integration Cloud rate limits?",answer:"OIC has standard throttling (default tier ~120 requests/minute on inbound). The Atlantis integration scheduler respects these limits and batches updates appropriately. For high-volume environments (very large equipment master with frequent changes), we recommend the OIC standard or enterprise tier which raises the limits substantially. We have customers running this in production with no rate-limit issues at typical refinery scale."}];function l(){const a={"@context":"https://schema.org","@graph":[{"@type":"SoftwareApplication",name:"Atlantis Digital Twin — Oracle ERP Cloud Integration",applicationCategory:"BusinessApplication",operatingSystem:"Web",description:"Oracle Fusion ERP Cloud + Oracle EAM Cloud integration via Oracle Integration Cloud (OIC). Bi-directional asset master, inspection findings → Service Requests → Work Orders. 3-5 wk deploy.",offers:{"@type":"Offer",availability:"https://schema.org/InStock"},provider:{"@type":"Organization",name:"Atlantis NDT"}},{"@type":"Article",headline:"Atlantis Digital Twin — Oracle ERP Cloud Integration [2026]",datePublished:"2026-05-09",dateModified:"2026-05-09",author:{"@type":"Person",name:"Anoop Rayavarapu"},publisher:{"@type":"Organization",name:"Atlantis NDT"}},{"@type":"FAQPage",mainEntity:i.map(t=>({"@type":"Question",name:t.question,acceptedAnswer:{"@type":"Answer",text:t.answer}}))}]};return e.jsx(n,{title:"Atlantis Digital Twin — Oracle ERP Cloud Integration: Fusion, EAM, EBS [2026]",description:"Oracle Fusion ERP Cloud + Oracle EAM Cloud integration: REST via Oracle Integration Cloud (OIC), bi-directional asset master, inspection findings → Service Requests → Work Orders. 3-5 wk deploy.",canonical:"https://atlantisndt.com/integrations/oracle-erp-cloud",eyebrow:"Integration",h1:"Atlantis Digital Twin — Oracle ERP Cloud Integration: Fusion, EAM Cloud, E-Business Suite [2026]",intro:"Bi-directional REST integration to Oracle Fusion ERP Cloud and Oracle EAM Cloud via Oracle Integration Cloud (OIC). Asset master flows Oracle → Atlantis; inspection findings, FFS/RBI results, and recommended work flow Atlantis → Oracle as Service Requests. 3–5 weeks to production.",heroGradient:"from-red-700 to-orange-700",competitorLabel:"Notes",compareRows:r,faqs:i,related:[{href:"/integrations/sap-pm",title:"SAP PM Integration",blurb:"Equivalent integration for SAP shops."},{href:"/integrations/ibm-maximo",title:"IBM Maximo Integration",blurb:"EAM-class integration alternative for non-Oracle shops."},{href:"/integrations/meridium-apm",title:"Meridium APM Integration",blurb:"RBI library sync + bidirectional inspection records."},{href:"/digital-twins",title:"Atlantis Digital Twin",blurb:"Product page — features, pricing, case studies."},{href:"/erp",title:"Atlantis NDT ERP",blurb:"Companion ERP — jobs, certs, equipment, invoicing."},{href:"/contact",title:"Book a Scoping Call",blurb:"60-minute call with a Level III consultant + integration architect."}],ctaTitle:"Plug Atlantis Into Your Oracle ERP",ctaSubtitle:"Bring your Oracle module list and a sample asset export. We’ll show the integration in 30 minutes.",structuredData:a,bodyChildren:e.jsxs(e.Fragment,{children:[e.jsx("h2",{children:"Architecture overview"}),e.jsx("p",{children:"Atlantis Digital Twin connects to Oracle Fusion ERP Cloud and Oracle EAM Cloud via Oracle Integration Cloud (OIC). OIC handles authentication (OAuth2 client credentials via Oracle Identity Cloud Service), throttling, retry, and orchestration. Atlantis registers as an OIC connection with read access to Asset / Maintenance Plan / Cost Center and write access to Service Request. We do not require Oracle administrator privileges and do not modify the Oracle schema."}),e.jsx("h2",{children:"Data flow"}),e.jsx("p",{children:"Asset master and asset hierarchy flow Oracle → Atlantis on a scheduled sync (default: every 4 hours, configurable). Oracle is the system of record. Atlantis attaches its inspection-domain extensions (CMLs, weld registers, RT/UT/PAUT scan archive, FFS calculations, RBI band) in its own data model, keyed to the Oracle Asset ID. Oracle is not extended."}),e.jsx("p",{children:"Inspection findings, FFS results, and RBI risk-band changes flow Atlantis → Oracle as Service Requests with structured long descriptions and deep links back to the full Atlantis record. Service Requests then route into the standard Oracle Maintenance Work Order workflow per your site’s ticket triage rules. We do not directly create Work Orders from Atlantis — Service Request is the right entry point in the Oracle planning workflow."}),e.jsx("p",{children:"Cost actuals, Work Order completion, technician assignment, and parts consumption flow Oracle → Atlantis on Work Order close. This closes the loop in Atlantis and feeds the integrity-program KPI dashboards."}),e.jsx("h2",{children:"Deployment timeline"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Week 1:"})," Oracle / OIC kickoff, integration user provisioning, OAuth2 setup, sandbox connection test."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Week 2:"})," Initial asset master import, hierarchy validation, Service Request create test."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Week 3:"})," User acceptance testing with the integrity team, edge case validation."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Week 4–5:"})," Production cut-over, monitoring live, hypercare."]})]}),e.jsx("h2",{children:"OIC tier recommendations"}),e.jsx("p",{children:"For typical refinery / petrochemical / FPSO scale (5,000–25,000 equipment items, daily inspection capture by 5–20 users), the OIC standard tier is sufficient. For large multi-site operators (100,000+ equipment items, sub-hourly sync windows), the OIC enterprise tier raises rate limits and concurrency caps to comfortable headroom. We’ll recommend the right tier during scoping based on your equipment count and update frequency."}),e.jsx("h2",{children:"Oracle E-Business Suite (legacy) notes"}),e.jsx("p",{children:"Customers on Oracle E-Business Suite (EBS) — typically 12.x — integrate via OIC’s EBS adapter, which abstracts the older PL/SQL and database interfaces. The functional integration is identical to Fusion ERP Cloud from Atlantis’ perspective. Implementation is slightly longer (5 weeks vs 3) because EBS landscapes typically have more customization and less standard data shapes than Fusion Cloud. We have customers running this in production."})]})})}export{l as default};
